import{INITIAL_STATES,SEASONS}from"./monsoon-data.js";export class MonsoonEngine{constructor(){this.listeners=[],this.resetGame()}resetGame(){this.state={score:0,multiplier:1,seasonIndex:0,timer:SEASONS[0].durationSec,statesData:JSON.parse(JSON.stringify(INITIAL_STATES)),gameOver:!1,gameWon:!1,reason:""},this.notifyListeners()}startEngine(){this.gameInterval&&clearInterval(this.gameInterval),this.gameInterval=setInterval(()=>this.gameTick(),1e3)}stopEngine(){this.gameInterval&&clearInterval(this.gameInterval)}subscribe(t){return this.listeners.push(t),()=>{this.listeners=this.listeners.filter(e=>e!==t)}}notifyListeners(){this.listeners.forEach(t=>t(this.state,this.getCurrentSeason()))}getCurrentSeason(){return SEASONS[this.state.seasonIndex]}gameTick(){if(this.state.gameOver)return;const t=this.getCurrentSeason();if(this.state.timer-=1,this.state.timer<=0){if(this.state.seasonIndex++,this.state.seasonIndex>=SEASONS.length)return void this.checkWinCondition(!0);this.state.timer=SEASONS[this.state.seasonIndex].durationSec}this.state.statesData.forEach(e=>{e.waterLevel-=t.evaporationRate,this.updateStatus(e)}),this.updateMultiplier(),this.state.score+=10*this.state.multiplier,this.checkLoseCondition(),this.notifyListeners()}rain(t){if(this.state.gameOver)return;const e=this.state.statesData.find(e=>e.id===t);if(e){const t=this.getCurrentSeason();e.waterLevel+=t.rainPower,this.updateStatus(e),this.updateMultiplier(),this.notifyListeners()}}updateStatus(t){t.waterLevel<t.minWater?t.status="Drought":t.waterLevel>t.maxWater?t.status="Flood":t.status="Balanced"}updateMultiplier(){const t=this.state.statesData.filter(t=>"Balanced"===t.status).length;this.state.multiplier=t>=6?5:t>=4?3:t>=2?2:1;const e=this.state.statesData.filter(t=>"Balanced"!==t.status).length;this.state.score-=5*e,this.state.score<0&&(this.state.score=0)}checkLoseCondition(){const t=this.state.statesData.filter(t=>"Flood"===t.status).length,e=this.state.statesData.filter(t=>"Drought"===t.status).length;(t>=3||e>=3)&&(this.state.gameOver=!0,this.state.gameWon=!1,this.state.reason="Too many states experienced extreme weather (Floods/Droughts).",this.stopEngine(),this.notifyListeners())}checkWinCondition(t){if(t){this.state.statesData.filter(t=>"Balanced"===t.status).length>=this.state.statesData.length/2?(this.state.gameOver=!0,this.state.gameWon=!0,this.state.reason="You survived the year maintaining balance in most states!"):(this.state.gameOver=!0,this.state.gameWon=!1,this.state.reason="Time is up, but too many states were left in poor conditions."),this.stopEngine(),this.notifyListeners()}}}export const monsoonEngine=new MonsoonEngine;